(910571, 104495, 18415, '<td valign="top">Great shot! Nothing beats Friday night high school football. You captured it all right down to the muscles on the players. Intresting angle as well. Good Luck!</td>', 'Great shot! Nothing beats Friday night high school football. You captured it all right down to the muscles on the players. Intresting angle as well. Good Luck!', '2004-09-15 03:01:23.000000', NULL, 1),
(910572, 104557, 25906, '<td valign="top">This photo is very busy</td>', 'This photo is very busy', '2004-09-15 03:03:25.000000', NULL, 1),
(910576, 105393, 24511, '<td valign="top">Ain''t no team sport like a tug-o-war.  I only see the number two guy giving it all he has.  Unfortunately facial grimacing doesn''t get you extra points for pulling on the rope as does focus and muscles.  It does however give this photographer a higher score.  Great angle shot and love the dead tree background on the right.</td>', 'Ain''t no team sport like a tug-o-war.  I only see the number two guy giving it all he has.  Unfortunately facial grimacing doesn''t get you extra points for pulling on the rope as does focus and muscles.  It does however give this photographer a higher score.  Great angle shot and love the dead tree background on the right.', '2004-09-15 03:08:56.000000', NULL, 1),
(910578, 104394, 24511, '<td valign="top">Warm colors made me lose the essence of team sports and broke my rythm during the voting process.</td>', 'Warm colors made me lose the essence of team sports and broke my rythm during the voting process.', '2004-09-15 03:12:59.000000', NULL, 1),
(910598, 104741, 93, '<td valign="top">There''s always got to be at least one on every site... wasting everyone''s time.</td>', 'There''s always got to be at least one on every site... wasting everyone''s time.', '2004-09-15 03:37:43.000000', NULL, 1),
(910600, 104848, 93, '<td valign="top">Sorry, but putting 4x100 relay in the title doesn''t make swimming a TEAM sport :)<br/> <br/>Nice try though.</td>', 'Sorry, but putting 4x100 relay in the title doesn''t make swimming a TEAM sport :) Nice try though.', '2004-09-15 03:40:17.000000', NULL, 1),
