(910728, 105256, 12962, '<td valign="top">Stop action!</td>', 'Stop action!', '2004-09-15 04:19:50.000000', NULL, 1),
(910735, 105196, 12962, '<td valign="top">Sometimes the head on the foreground allows the reader to be part of the audience but sometimes it doesn''t work.  It doesn''t work for me this time.  Sorry.  I like the action frozen on the turf though.</td>', 'Sometimes the head on the foreground allows the reader to be part of the audience but sometimes it doesn''t work.  It doesn''t work for me this time.  Sorry.  I like the action frozen on the turf though.', '2004-09-15 04:25:59.000000', NULL, 1),
(910737, 104630, 24128, '<td valign="top">Love the expressions, great capture, someone should tell the guy with the ball to tie his shoelaces though - he might trip over :)</td>', 'Love the expressions, great capture, someone should tell the guy with the ball to tie his shoelaces though - he might trip over :)', '2004-09-15 04:27:06.000000', NULL, 1),
(910738, 104741, 12962, '<td valign="top">Beautiful picture!</td>', 'Beautiful picture!', '2004-09-15 04:27:43.000000', NULL, 1),
(910741, 104935, 12962, '<td valign="top">Love the elegance. 10.</td>', 'Love the elegance. 10.', '2004-09-15 04:28:25.000000', NULL, 1),
(910744, 105480, 24128, '<td valign="top">Good pic, the focus on the 3rd guy''s helmet is excellent - just wish that you had managed to get that on the guy in the middle</td>', 'Good pic, the focus on the 3rd guy''s helmet is excellent - just wish that you had managed to get that on the guy in the middle', '2004-09-15 04:29:37.000000', NULL, 1),
(910745, 104495, 12962, '<td valign="top">I like the tilt, it gives it more motion.</td>', 'I like the tilt, it gives it more motion.', '2004-09-15 04:29:50.000000', NULL, 1),
(910748, 105400, 12962, '<td valign="top">At least it''s not football :-).   Beautiful shot!</td>', 'At least it''s not football :-).   Beautiful shot!', '2004-09-15 04:31:25.000000', NULL, 1),
(910750, 105400, 24128, '<td valign="top">nice pic, and a well deserved boost in points for submitting something original :)</td>', 'nice pic, and a well deserved boost in points for submitting something original :)', '2004-09-15 04:32:28.000000', NULL, 1),
(910754, 105308, 12962, '<td valign="top">Desaturation gives a nostalgic feel.  Good job!</td>', 'Desaturation gives a nostalgic feel.  Good job!', '2004-09-15 04:33:09.000000', NULL, 1);
