(911371, 104079, 15575, '<td valign="top">I don''t mind the fence so much, but find the head distracting</td>', 'I don''t mind the fence so much, but find the head distracting', '2004-09-15 12:27:49.000000', NULL, 1),
(911372, 104712, 25330, '<td valign="top">This is a nice concept, but the soft focus is distracting to me.</td>', 'This is a nice concept, but the soft focus is distracting to me.', '2004-09-15 12:28:22.000000', NULL, 1),
(911373, 104557, 25623, '<td valign="top">You really should NOT have messed with the selective desaturation.  The picture would have been at least a &lt;7&gt; had you not messed with it.  Now IMHO it just looks tacky and out of place.  Never mess with it when you already have a good thing.</td>', 'You really should NOT have messed with the selective desaturation.  The picture would have been at least a <7> had you not messed with it.  Now IMHO it just looks tacky and out of place.  Never mess with it when you already have a good thing.', '2004-09-15 12:28:57.000000', NULL, 1),
