INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(911468, 104848, 22922, '<td valign="top">Nice capture, but not very interesting composition-wise.  The water is pretty.</td>', 'Nice capture, but not very interesting composition-wise.  The water is pretty.', '2004-09-15 13:15:00.000000', NULL, 1),
(911471, 104495, 24846, '<td valign="top">Like the angle. Lots to see, runner, blocker. Looks like holding on the offense  with the facemask. Fits challenge well.</td>', 'Like the angle. Lots to see, runner, blocker. Looks like holding on the offense  with the facemask. Fits challenge well.', '2004-09-15 13:16:47.000000', NULL, 1),
(911472, 104076, 22922, '<td valign="top">I get what you''re saying, but there''s not enough in the image to keep my interest, no action, and hard to say what emotion is conveyed without the title.  Did everything go wrong because he missed the ball, or is everything happening on the other end of the field, leaving him with nothing to do?</td>', 'I get what you''re saying, but there''s not enough in the image to keep my interest, no action, and hard to say what emotion is conveyed without the title.  Did everything go wrong because he missed the ball, or is everything happening on the other end of the field, leaving him with nothing to do?', '2004-09-15 13:17:22.000000', NULL, 1),
