(913573, 105379, 23561, '<td valign="top">Great capture. Might have cropped just a bit different. The background has a nice soft blur but the (I guess) coach and goalie distract a bit because of the different colors in their clothes compare with the rest of the shot. Still above average.</td>', 'Great capture. Might have cropped just a bit different. The background has a nice soft blur but the (I guess) coach and goalie distract a bit because of the different colors in their clothes compare with the rest of the shot. Still above average.', '2004-09-16 20:00:51.000000', NULL, 1),
(913584, 104518, 23561, '<td valign="top">Good use of B&amp;W, comp and lighting are good. I do think that this frame detracts a little from the picture because the white frame is brighter than the white ball or shirt worn by the player. Still an above average score. Like the expression, more of an "I''m happy to be playing" rather than an "i gotta get this" look.</td>', 'Good use of B&W, comp and lighting are good. I do think that this frame detracts a little from the picture because the white frame is brighter than the white ball or shirt worn by the player. Still an above average score. Like the expression, more of an "I''m happy to be playing" rather than an "i gotta get this" look.', '2004-09-16 20:06:23.000000', NULL, 1),
(913585, 105460, 8437, '<td valign="top">Really nice picture. I would crop the bottom tree, however.</td>', 'Really nice picture. I would crop the bottom tree, however.', '2004-09-16 20:06:26.000000', NULL, 1),
