(914252, 105400, 26334, '<td valign="top">hahahaa... wonder how the rules is</td>', 'hahahaa... wonder how the rules is', '2004-09-17 06:23:13.000000', NULL, 1),
(914254, 105296, 23300, '<td valign="top">Great use of cropping. I really get a sense of the energy in this image.</td>', 'Great use of cropping. I really get a sense of the energy in this image.', '2004-09-17 06:24:03.000000', NULL, 1),
(914259, 105297, 23300, '<td valign="top">I like the sense of space in this image. Somehow the open space and lighting creates a sense of intimacy amoung the players. I feel that cropping a bit off the bottom and a smaller bit off the top to emphasize the horizontal would enhance the mood somehow. Good Luck in the challenge.</td>', 'I like the sense of space in this image. Somehow the open space and lighting creates a sense of intimacy amoung the players. I feel that cropping a bit off the bottom and a smaller bit off the top to emphasize the horizontal would enhance the mood somehow. Good Luck in the challenge.', '2004-09-17 06:29:28.000000', NULL, 1),
(914266, 104557, 26526, '<td valign="top">I really like this photo. I was going to vote it down because of certain areas desaturated, others aren''t. Or so it appears to me. See it had been validated, so that means I am confused. Will up your score. How did you do it?</td>', 'I really like this photo. I was going to vote it down because of certain areas desaturated, others aren''t. Or so it appears to me. See it had been validated, so that means I am confused. Will up your score. How did you do it?', '2004-09-17 06:32:10.000000', NULL, 1),
(914268, 105396, 23300, '<td valign="top">Great composition. Great tonal contrast. Truly artistic in its execution. Well done.</td>', 'Great composition. Great tonal contrast. Truly artistic in its execution. Well done.', '2004-09-17 06:34:17.000000', NULL, 1),
(914272, 105453, 23300, '<td valign="top">I think the rich colours work well and the cropping enhances the action.</td>', 'I think the rich colours work well and the cropping enhances the action.', '2004-09-17 06:44:35.000000', NULL, 1),
(914276, 104650, 21158, '<td valign="top">the image seems a little grainy.</td>', 'the image seems a little grainy.', '2004-09-17 07:19:15.000000', NULL, 1),
(914277, 104849, 21158, '<td valign="top">it looks a tad OOF.</td>', 'it looks a tad OOF.', '2004-09-17 07:21:16.000000', NULL, 1),
(914279, 105467, 21158, '<td valign="top">not bad. has just a little bit of noise...7</td>', 'not bad. has just a little bit of noise...7', '2004-09-17 07:24:51.000000', NULL, 1),
(914310, 104630, 26653, '<td valign="top">Oh no, his shoe''s untied!<br/>Great shot.</td>', 'Oh no, his shoe''s untied!Great shot.', '2004-09-17 08:53:10.000000', NULL, 1),
(914311, 105196, 26653, '<td valign="top">good action.  That head is a big distraction tho. too bad.</td>', 'good action.  That head is a big distraction tho. too bad.', '2004-09-17 08:54:17.000000', NULL, 1),
(914312, 105445, 26653, '<td valign="top">Would have been so much better if they were running toward you instead of away.  Their faces can add so much.</td>', 'Would have been so much better if they were running toward you instead of away.  Their faces can add so much.', '2004-09-17 08:55:19.000000', NULL, 1),
(914313, 105237, 25355, '<td valign="top">greta shot, but I would have liked to have seen the whole of his left foot in the pic as well.</td>', 'greta shot, but I would have liked to have seen the whole of his left foot in the pic as well.', '2004-09-17 08:56:04.000000', NULL, 1),
(914314, 104822, 26653, '<td valign="top">great panaorama.</td>', 'great panaorama.', '2004-09-17 08:56:04.000000', NULL, 1),
(914315, 105031, 26653, '<td valign="top">Look at all that expression!  Thanks for including faces!</td>', 'Look at all that expression!  Thanks for including faces!', '2004-09-17 08:56:46.000000', NULL, 1),
(914318, 105237, 26653, '<td valign="top">Very cool,  wish his foot wasn''t cut off.  And if it was set up?? more light on his face.<br/>Still and all, very cool!</td>', 'Very cool,  wish his foot wasn''t cut off.  And if it was set up?? more light on his face.Still and all, very cool!', '2004-09-17 08:58:42.000000', NULL, 1),
(914319, 105184, 25355, '<td valign="top">Nice primary colours, but I would have liked a picture showing their faces. And how did Dapto do?</td>', 'Nice primary colours, but I would have liked a picture showing their faces. And how did Dapto do?', '2004-09-17 08:59:27.000000', NULL, 1),
(914321, 105476, 25355, '<td valign="top">Not very interesting, sorry.</td>', 'Not very interesting, sorry.', '2004-09-17 09:01:56.000000', NULL, 1),
(914324, 105401, 25355, '<td valign="top">Nice shot. I like how the blurry background complements the tonal range of the colours in the two players. And the guy''s eyebrows - are they real, or pencilled in like that?!</td>', 'Nice shot. I like how the blurry background complements the tonal range of the colours in the two players. And the guy''s eyebrows - are they real, or pencilled in like that?!', '2004-09-17 09:04:44.000000', NULL, 1),
(914325, 105438, 25355, '<td valign="top">Good stop-action shot under such lighting conditions.</td>', 'Good stop-action shot under such lighting conditions.', '2004-09-17 09:06:26.000000', NULL, 1),
(914327, 104935, 25355, '<td valign="top">Excellent clarity, no motion blur at all. In my top 6.</td>', 'Excellent clarity, no motion blur at all. In my top 6.', '2004-09-17 09:07:59.000000', NULL, 1),
(914328, 105473, 20494, '<td valign="top">blurrrrry</td>', 'blurrrrry', '2004-09-17 09:08:12.000000', NULL, 1),
(914388, 104491, 26087, '<td valign="top">Good picture.</td>', 'Good picture.', '2004-09-17 11:03:21.000000', NULL, 1),
(914390, 104726, 26087, '<td valign="top">Good picture.</td>', 'Good picture.', '2004-09-17 11:04:17.000000', NULL, 1),
(914391, 105478, 26087, '<td valign="top">Good picture.</td>', 'Good picture.', '2004-09-17 11:04:43.000000', NULL, 1),
(914404, 105478, 16230, '<td valign="top">Great action shot!</td>', 'Great action shot!', '2004-09-17 11:13:07.000000', NULL, 1),
(914441, 104495, 3102, '<td valign="top">Nicely done!  High school games are so hard to do because they typically have so little light.  You seem to have pulled it off nicely here.</td>', 'Nicely done!  High school games are so hard to do because they typically have so little light.  You seem to have pulled it off nicely here.', '2004-09-17 11:59:02.000000', NULL, 1),
(914442, 104887, 3102, '<td valign="top">I like this one a lot!  I like the repetition and the simplicity of it all.  In a way, all of these random numbers remind me of scary math class dreams I''ve had!</td>', 'I like this one a lot!  I like the repetition and the simplicity of it all.  In a way, all of these random numbers remind me of scary math class dreams I''ve had!', '2004-09-17 12:00:25.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(914443, 105400, 3102, '<td valign="top">Definitely a unique take on the challenge -- I wouldn''t have thought of that!  This is one of my favorites.</td>', 'Definitely a unique take on the challenge -- I wouldn''t have thought of that!  This is one of my favorites.', '2004-09-17 12:01:06.000000', NULL, 1),
(914447, 105484, 3102, '<td valign="top">Well done!  You caught a good moment, no doubt!  I''m sure plenty of people are whining about the fact that the runner''s foot isn''t entirely in the shot, but I don''t find that to be much of a big deal.</td>', 'Well done!  You caught a good moment, no doubt!  I''m sure plenty of people are whining about the fact that the runner''s foot isn''t entirely in the shot, but I don''t find that to be much of a big deal.', '2004-09-17 12:02:06.000000', NULL, 1),
(914449, 105260, 3102, '<td valign="top">Cool shot at a good moment!  It would have been nice to see more of their faces, but you can''t exactly ask them to turn their heads mid-jump :)</td>', 'Cool shot at a good moment!  It would have been nice to see more of their faces, but you can''t exactly ask them to turn their heads mid-jump :)', '2004-09-17 12:02:55.000000', NULL, 1),
(914451, 104844, 3102, '<td valign="top">Good job of getting in close!  Overall I like this shot a lot, but I have a couple suggestions.  I might have cropped JUST the runner, eliminating much of the rest of the image.  It''s not always easy to accomplish, but this would have been better with a shallower depth of field -- as it is, the spectators are in good enough focus that they really compete for attention with the subject.</td>', 'Good job of getting in close!  Overall I like this shot a lot, but I have a couple suggestions.  I might have cropped JUST the runner, eliminating much of the rest of the image.  It''s not always easy to accomplish, but this would have been better with a shallower depth of field -- as it is, the spectators are in good enough focus that they really compete for attention with the subject.', '2004-09-17 12:04:49.000000', NULL, 1),
(914456, 105446, 3102, '<td valign="top">Nice job getting right up close!  Night games are tricky, unless you have one heck of a nice lens.  The contrast seems just a teeny bit much here, and there might be a tad bit too much yellow, but overall you pulled it off nicely.</td>', 'Nice job getting right up close!  Night games are tricky, unless you have one heck of a nice lens.  The contrast seems just a teeny bit much here, and there might be a tad bit too much yellow, but overall you pulled it off nicely.', '2004-09-17 12:10:47.000000', NULL, 1),
(914457, 104079, 3102, '<td valign="top">The giant hat in the way is a bit of a distraction... you caught the shot at a good momen, though.</td>', 'The giant hat in the way is a bit of a distraction... you caught the shot at a good momen, though.', '2004-09-17 12:12:06.000000', NULL, 1),
(914514, 105379, 26087, '<td valign="top">Good picture/</td>', 'Good picture/', '2004-09-17 13:24:28.000000', NULL, 1),
(914518, 105400, 23338, '<td valign="top">I don''t understand ...  These firemen have "Girlie legs"?   :-)   Actually, I really like the image.  It has bright color contrasts, action, perspective, pretty good focus - at least on the central area of interest, and I really like how everything gets hazier as you move back further into the image (obviously due to the mist and spray in the air).  And, it''s different than everything else.  Congratulations and good luck in the challenge.</td>', 'I don''t understand ...  These firemen have "Girlie legs"?   :-)   Actually, I really like the image.  It has bright color contrasts, action, perspective, pretty good focus - at least on the central area of interest, and I really like how everything gets hazier as you move back further into the image (obviously due to the mist and spray in the air).  And, it''s different than everything else.  Congratulations and good luck in the challenge.', '2004-09-17 13:27:31.000000', NULL, 1),
(914521, 105420, 23338, '<td valign="top">Needs just a tad more DOF.   Seems to have really captured the moment and the contrasts between the stark white goal netting and the absolute black sky behind is great.  Would have rated it higher except for the DOF point.  Congratulations.  Good luck with the challenge.</td>', 'Needs just a tad more DOF.   Seems to have really captured the moment and the contrasts between the stark white goal netting and the absolute black sky behind is great.  Would have rated it higher except for the DOF point.  Congratulations.  Good luck with the challenge.', '2004-09-17 13:30:27.000000', NULL, 1),
(914526, 105308, 23338, '<td valign="top">This is a really nice composition.   Love the huge "canvas" of grass with the three little figures at the bottom.  Wish there was a little more focus on the players though.  Good luck with the challenge.</td>', 'This is a really nice composition.   Love the huge "canvas" of grass with the three little figures at the bottom.  Wish there was a little more focus on the players though.  Good luck with the challenge.', '2004-09-17 13:32:50.000000', NULL, 1),
(914536, 104730, 23338, '<td valign="top">Could have worked equally well in the challenge on stopping motion.  Really neat image.  Focus and composition are great.  Don''t know what you did regarding tone, but the toning in this image really lends itself to the depiction of the human being arrested right in the middle, too.  Man isn''t it neat how that water just hangs there?  Love the image.   Good luck in the challenge.</td>', 'Could have worked equally well in the challenge on stopping motion.  Really neat image.  Focus and composition are great.  Don''t know what you did regarding tone, but the toning in this image really lends itself to the depiction of the human being arrested right in the middle, too.  Man isn''t it neat how that water just hangs there?  Love the image.   Good luck in the challenge.', '2004-09-17 13:36:18.000000', NULL, 1),
(914538, 104887, 23338, '<td valign="top">There are a FEW images in this challenge that look artsy, and this is the best.  I really like the sea of repitition with blues jerseys, orange numbers, shiney helmets with their rising ray pattern - it''s really great.  Detail gets just a little fuzzy on one helmet toward the top where the action wasn''t quite stopped.  Good luck in the challenge.</td>', 'There are a FEW images in this challenge that look artsy, and this is the best.  I really like the sea of repitition with blues jerseys, orange numbers, shiney helmets with their rising ray pattern - it''s really great.  Detail gets just a little fuzzy on one helmet toward the top where the action wasn''t quite stopped.  Good luck in the challenge.', '2004-09-17 13:38:52.000000', NULL, 1),
(914539, 105442, 20433, '<td valign="top">Try always using the full width that DPC allows (640 px)</td>', 'Try always using the full width that DPC allows (640 px)', '2004-09-17 13:38:52.000000', NULL, 1),
(914543, 105251, 20433, '<td valign="top">Would have liked to see some action in this photo.</td>', 'Would have liked to see some action in this photo.', '2004-09-17 13:42:27.000000', NULL, 1),
(914545, 105393, 23338, '<td valign="top">Geez, tug-a-wars are really fun.   Not too many people get involved in them anymore.  Guess there were a few accidents.   This image has a pretty nice composition in terms of the arrangement of the players.  It could use a teeny bit more focus on the closest arm and I''d love to lose some of the competing background objects - specifically the dead tree.  But, it is reflective of the action and effort involved and it is a different kind of sport than your normal football, basketball, baseball, etc.  Nice shot.  Good luck in the challenge.</td>', 'Geez, tug-a-wars are really fun.   Not too many people get involved in them anymore.  Guess there were a few accidents.   This image has a pretty nice composition in terms of the arrangement of the players.  It could use a teeny bit more focus on the closest arm and I''d love to lose some of the competing background objects - specifically the dead tree.  But, it is reflective of the action and effort involved and it is a different kind of sport than your normal football, basketball, baseball, etc.  Nice shot.  Good luck in the challenge.', '2004-09-17 13:43:06.000000', NULL, 1),
(914550, 105317, 23338, '<td valign="top">Really nice composition - and a great moment of action.  You can really see the strain and stress in every muscle of the player''s body.  I used to love watching high school basketball, especially when my son was playing varsity.  The hardest thing for me to do was stop the right moment of action and have a good balance of movement and focus to portray it.  Congratulations and good luck in the challenge.</td>', 'Really nice composition - and a great moment of action.  You can really see the strain and stress in every muscle of the player''s body.  I used to love watching high school basketball, especially when my son was playing varsity.  The hardest thing for me to do was stop the right moment of action and have a good balance of movement and focus to portray it.  Congratulations and good luck in the challenge.', '2004-09-17 13:46:22.000000', NULL, 1),
(914556, 105248, 20433, '<td valign="top">Way to much noise.</td>', 'Way to much noise.', '2004-09-17 13:48:52.000000', NULL, 1),
(914558, 104495, 23338, '<td valign="top">Cool.  Two teams in blue and white uniforms so that you can get good color and contrast against the night sky.  The way the shot was taken, with the ground sloping at a sharp angle to the right and the play in motion to that direction, is really effective.  Nice focus and stop action on the center of the play.  Nice visual balance between the bodies of the opposing players.  Congratulations.  Good luck in the challenge.</td>', 'Cool.  Two teams in blue and white uniforms so that you can get good color and contrast against the night sky.  The way the shot was taken, with the ground sloping at a sharp angle to the right and the play in motion to that direction, is really effective.  Nice focus and stop action on the center of the play.  Nice visual balance between the bodies of the opposing players.  Congratulations.  Good luck in the challenge.', '2004-09-17 13:49:51.000000', NULL, 1),
(914562, 105446, 23338, '<td valign="top">Nice stop action and focus.  Great colors and contrasts.  Look at the muscles and stress in the ball carrier''s arm.  Geez.  Congratulations on a really nice image.   Good luck in the challenge.</td>', 'Nice stop action and focus.  Great colors and contrasts.  Look at the muscles and stress in the ball carrier''s arm.  Geez.  Congratulations on a really nice image.   Good luck in the challenge.', '2004-09-17 13:52:09.000000', NULL, 1),
(914564, 105235, 23338, '<td valign="top">Not too many regatta photos in the challenge - and they make such nice subjects.   I think your composition and colors are really great - I just wish there was a little more focus on the 2nd and 3rd boats.  Good luck with the challenge.</td>', 'Not too many regatta photos in the challenge - and they make such nice subjects.   I think your composition and colors are really great - I just wish there was a little more focus on the 2nd and 3rd boats.  Good luck with the challenge.', '2004-09-17 13:54:14.000000', NULL, 1),
(914569, 105379, 23338, '<td valign="top">Half the action and fun in a sporting event is the reactions of the crowd.  Would you look at the faces of the players on the bench?   Nice stop action on the field, good focus where it counts, good colors and lighting.  I would have cropped out the two people standing on the right and then tried to get rid of some of the blurry white in the upper part of the image in the background.  But, hey, that''s just me.  Good luck in the challenge.</td>', 'Half the action and fun in a sporting event is the reactions of the crowd.  Would you look at the faces of the players on the bench?   Nice stop action on the field, good focus where it counts, good colors and lighting.  I would have cropped out the two people standing on the right and then tried to get rid of some of the blurry white in the upper part of the image in the background.  But, hey, that''s just me.  Good luck in the challenge.', '2004-09-17 13:57:53.000000', NULL, 1),
(914571, 105478, 23338, '<td valign="top">Such a ballet of action!  9/10s of any image is getting the right moment in time - which is very difficult to do.  Great focus, contrasts, colors and composition.  I really like it.  Good luck in the challenge.</td>', 'Such a ballet of action!  9/10s of any image is getting the right moment in time - which is very difficult to do.  Great focus, contrasts, colors and composition.  I really like it.  Good luck in the challenge.', '2004-09-17 13:59:31.000000', NULL, 1),
(914576, 105260, 24454, '<td valign="top">Great stop-action.  Everything is sharp and clear.    Really nice picture!</td>', 'Great stop-action.  Everything is sharp and clear.    Really nice picture!', '2004-09-17 14:01:45.000000', NULL, 1),
(914580, 105170, 24454, '<td valign="top">Nice vivid colors.  I love how it''s so crisp and clear.</td>', 'Nice vivid colors.  I love how it''s so crisp and clear.', '2004-09-17 14:04:02.000000', NULL, 1),
(914582, 105198, 24454, '<td valign="top">I like how they are all running away -- in the same direction -- same angle.  Makes it interesting &amp; unique  :)</td>', 'I like how they are all running away -- in the same direction -- same angle.  Makes it interesting & unique  :)', '2004-09-17 14:05:50.000000', NULL, 1),
(914584, 105400, 24454, '<td valign="top">How cool!   What a great picture!</td>', 'How cool!   What a great picture!', '2004-09-17 14:08:15.000000', NULL, 1),
(914592, 105473, 23338, '<td valign="top">Action IS being shown by motion, yes, but my personal opinion is that there is too much blur here and not enough definition.  In addition, it''s so dark.  I would have hyped the colors and contrasts more - if that were possible given your equipment and situation.  Anyway, good luck in the challenge.</td>', 'Action IS being shown by motion, yes, but my personal opinion is that there is too much blur here and not enough definition.  In addition, it''s so dark.  I would have hyped the colors and contrasts more - if that were possible given your equipment and situation.  Anyway, good luck in the challenge.', '2004-09-17 14:17:56.000000', NULL, 1),
(914594, 105210, 23338, '<td valign="top">The only thing in focus is the net!  Nice colors to work with, but I would have really changed the focus and concentrated on the player - even to the extent of blurring out the background.  Good luck with the challenge.</td>', 'The only thing in focus is the net!  Nice colors to work with, but I would have really changed the focus and concentrated on the player - even to the extent of blurring out the background.  Good luck with the challenge.', '2004-09-17 14:20:03.000000', NULL, 1),
(914597, 105394, 23338, '<td valign="top">So, is the subject a "blue crane" or a sport?   If it was the "crane" (where did you get Pelican?) then I would have cropped differently.  If it was a sport - I probably would have tried to concentrate on the boats without the crane, or maybe even waited until some rowers arrived and scared the crane away.  Nice focus and reflection though.  Good luck in the challenge.</td>', 'So, is the subject a "blue crane" or a sport?   If it was the "crane" (where did you get Pelican?) then I would have cropped differently.  If it was a sport - I probably would have tried to concentrate on the boats without the crane, or maybe even waited until some rowers arrived and scared the crane away.  Nice focus and reflection though.  Good luck in the challenge.', '2004-09-17 14:23:03.000000', NULL, 1),
(914601, 104023, 13365, '<td valign="top">Pure Genius!!</td>', 'Pure Genius!!', '2004-09-17 14:25:36.000000', NULL, 1),
(914603, 104394, 23338, '<td valign="top">This is such a strange, but interesting image.  I don''t really see what it is - and thus loose the "team sports" theme.  The closest I could come is that it was a play diagram of some sort, but the red and yellow?  And each dot is "x''d" out?  Why not Xs and Os?  I''m really lost.  Good luck with the challenge.</td>', 'This is such a strange, but interesting image.  I don''t really see what it is - and thus loose the "team sports" theme.  The closest I could come is that it was a play diagram of some sort, but the red and yellow?  And each dot is "x''d" out?  Why not Xs and Os?  I''m really lost.  Good luck with the challenge.', '2004-09-17 14:28:52.000000', NULL, 1),
(914605, 104802, 656, '<td valign="top">Very crisp, sharp shot of where the action was a split second ago.</td>', 'Very crisp, sharp shot of where the action was a split second ago.', '2004-09-17 14:30:06.000000', NULL, 1),
(914607, 104394, 26877, '<td valign="top">Sorry don''t know the sport enough</td>', 'Sorry don''t know the sport enough', '2004-09-17 14:30:59.000000', NULL, 1),
(914609, 105204, 23338, '<td valign="top">Didn''t really like the image that much, but TOTALLY got the idea.  And, it IS a team sport - one you don''t really see that much.  :-)  Would have liked slightly more detail so that it was less silhouettish - maybe some more "sidelighting".  Anyway, good luck with the challenge.</td>', 'Didn''t really like the image that much, but TOTALLY got the idea.  And, it IS a team sport - one you don''t really see that much.  :-)  Would have liked slightly more detail so that it was less silhouettish - maybe some more "sidelighting".  Anyway, good luck with the challenge.', '2004-09-17 14:31:46.000000', NULL, 1),
(914612, 105251, 26877, '<td valign="top">Nice picture, but no high speed action.</td>', 'Nice picture, but no high speed action.', '2004-09-17 14:34:10.000000', NULL, 1),
(914613, 105162, 23338, '<td valign="top">Pretty nice image, I think ... (while I try to ponder photographic technique vs. thos hideous teeth)    :-)    It just emphasizes something other than the actual sport; ie: fighting with the ref over a call.    Really great expression and perspective though.  Good luck with the challenge.</td>', 'Pretty nice image, I think ... (while I try to ponder photographic technique vs. thos hideous teeth)    :-)    It just emphasizes something other than the actual sport; ie: fighting with the ref over a call.    Really great expression and perspective though.  Good luck with the challenge.', '2004-09-17 14:35:08.000000', NULL, 1),
(914615, 105162, 26877, '<td valign="top">Great title</td>', 'Great title', '2004-09-17 14:35:45.000000', NULL, 1),
(914619, 105296, 26877, '<td valign="top">fabulous positioning, makes me want to ask: How did you take that shot?</td>', 'fabulous positioning, makes me want to ask: How did you take that shot?', '2004-09-17 14:37:33.000000', NULL, 1),
(914622, 104079, 25989, '<td valign="top">The back of the head (bottom) of this shot is distracting to me, otherwise good pciture</td>', 'The back of the head (bottom) of this shot is distracting to me, otherwise good pciture', '2004-09-17 14:40:39.000000', NULL, 1),
(914623, 105396, 26877, '<td valign="top">amazing shot, I think only true volleyball players will understand thought</td>', 'amazing shot, I think only true volleyball players will understand thought', '2004-09-17 14:41:05.000000', NULL, 1),
(914624, 104741, 26877, '<td valign="top">nice shot, but no subject matter</td>', 'nice shot, but no subject matter', '2004-09-17 14:47:07.000000', NULL, 1),
(914625, 104887, 26877, '<td valign="top">awesome shot, is this a crop of a bigger shot?</td>', 'awesome shot, is this a crop of a bigger shot?', '2004-09-17 14:48:08.000000', NULL, 1),
(914641, 104630, 12543, '<td valign="top">id like to see this shot taken 0.5 sec l8er</td>', 'id like to see this shot taken 0.5 sec l8er', '2004-09-17 15:15:03.000000', NULL, 1),
(914650, 104590, 21183, '<td valign="top">Well photographed ''action'' for this challenge.  Lots of interesting activity - but I wonder if the photo might fare better with the player over to the far left cropped out to give more balance to the image? Sorry unable to give more helpful advice - not a professional photographer myself.</td>', 'Well photographed ''action'' for this challenge.  Lots of interesting activity - but I wonder if the photo might fare better with the player over to the far left cropped out to give more balance to the image? Sorry unable to give more helpful advice - not a professional photographer myself.', '2004-09-17 15:43:26.000000', NULL, 1),
(914654, 104518, 21183, '<td valign="top">This looks a fun photograph and brings a smile to my face.  Plenty of action in the image too. I wonder, perhaps, if it would look even better with some extra contrast and without the ''horizontals'' of the line behind the figure and that of the road. Otherwise - a great capture, well done!</td>', 'This looks a fun photograph and brings a smile to my face.  Plenty of action in the image too. I wonder, perhaps, if it would look even better with some extra contrast and without the ''horizontals'' of the line behind the figure and that of the road. Otherwise - a great capture, well done!', '2004-09-17 15:52:05.000000', NULL, 1),
(914659, 105433, 21183, '<td valign="top">I really like this image.  It shouts of ''movement and action''. The shadows beneath the players feet are fascinatingly intricate, creating a nice ''base'' to the photo (along with the ball).  If this were mine I''d have cropped the goal post/nets away at the top, even though it would have meant the head of the player with the ball would have been tight to the frame - and hoped for the best.  Best of luck with this.</td>', 'I really like this image.  It shouts of ''movement and action''. The shadows beneath the players feet are fascinatingly intricate, creating a nice ''base'' to the photo (along with the ball).  If this were mine I''d have cropped the goal post/nets away at the top, even though it would have meant the head of the player with the ball would have been tight to the frame - and hoped for the best.  Best of luck with this.', '2004-09-17 15:58:16.000000', NULL, 1),
(914663, 105393, 21643, '<td valign="top">Thanks for an original entry! A team sport that almost all of us have played and yet that few of us would have thought to photograph for this challenge! In addition, the composition is great, and you captured the facial expressions perfectly. One of my favorite photos in this challenge. Good luck!<br/></td>', 'Thanks for an original entry! A team sport that almost all of us have played and yet that few of us would have thought to photograph for this challenge! In addition, the composition is great, and you captured the facial expressions perfectly. One of my favorite photos in this challenge. Good luck!', '2004-09-17 16:01:59.000000', NULL, 1),
(914672, 105255, 21643, '<td valign="top">I love the placement of the "athletes" in this shot. Everything about this picture draws the viewer into the action. Usually for an action-shot challenge, I''d prefer a shot with live people. However, this one is done well, it does indeed show action, and it looks like it was very hard to pull off! I''m anxious to see your comments on this photo after the challenge is over, because I''m interested in what techniques you used for this shot.<br/></td>', 'I love the placement of the "athletes" in this shot. Everything about this picture draws the viewer into the action. Usually for an action-shot challenge, I''d prefer a shot with live people. However, this one is done well, it does indeed show action, and it looks like it was very hard to pull off! I''m anxious to see your comments on this photo after the challenge is over, because I''m interested in what techniques you used for this shot.', '2004-09-17 16:09:31.000000', NULL, 1),
(914676, 105355, 21183, '<td valign="top">That looks like so much fun!  The kayaker appears to be enjoying the sport, despite the determined look. Plenty of action going on and the splashes of water add to it.  Pity that the focus is slightly blurred.  Wondering if you might have been able to get the kayak in full view without either the front or rear of it ''cropped''?</td>', 'That looks like so much fun!  The kayaker appears to be enjoying the sport, despite the determined look. Plenty of action going on and the splashes of water add to it.  Pity that the focus is slightly blurred.  Wondering if you might have been able to get the kayak in full view without either the front or rear of it ''cropped''?', '2004-09-17 16:12:09.000000', NULL, 1),
(914681, 105400, 21643, '<td valign="top">Great capture of the ball in mid-air, and an excellent angle from which to shoot this picture. Thanks also for photographing a unique team sport!<br/></td>', 'Great capture of the ball in mid-air, and an excellent angle from which to shoot this picture. Thanks also for photographing a unique team sport!', '2004-09-17 16:15:18.000000', NULL, 1),
(914686, 104888, 21183, '<td valign="top">I think the angle/tilt of this photo is good and makes for an interesting photograph. Though, if looked at for too long makes one feel a tad giddy/queasy. An 8 ...but might bump higher later on.</td>', 'I think the angle/tilt of this photo is good and makes for an interesting photograph. Though, if looked at for too long makes one feel a tad giddy/queasy. An 8 ...but might bump higher later on.', '2004-09-17 16:22:06.000000', NULL, 1),
(914689, 105442, 21183, '<td valign="top">There looks to be some interesting action going on in the photo and I like the way the green areas frame the brown of the playing pitch. Just wondering why this image is so small - I think it would score much higher if had been larger.</td>', 'There looks to be some interesting action going on in the photo and I like the way the green areas frame the brown of the playing pitch. Just wondering why this image is so small - I think it would score much higher if had been larger.', '2004-09-17 16:27:39.000000', NULL, 1),
(914691, 104023, 24642, '<td valign="top">Very minimalistic, but I can''t relate it to Team Sport Action.</td>', 'Very minimalistic, but I can''t relate it to Team Sport Action.', '2004-09-17 16:29:57.000000', NULL, 1),
(914695, 105308, 21183, '<td valign="top">This photo is lovely - it''s made interesting to me by the use of negative space above the players and the pattern in the space created by the cut grass. The players shadows create an interesting contrast too. I''m not too keen on the graininess of the photo, however, though I have to say I have similar problems when taking zoom photos with my camera on high ISO settings.</td>', 'This photo is lovely - it''s made interesting to me by the use of negative space above the players and the pattern in the space created by the cut grass. The players shadows create an interesting contrast too. I''m not too keen on the graininess of the photo, however, though I have to say I have similar problems when taking zoom photos with my camera on high ISO settings.', '2004-09-17 16:32:55.000000', NULL, 1),
(914698, 105186, 24642, '<td valign="top">A good shot, shame it isn''t bigger.</td>', 'A good shot, shame it isn''t bigger.', '2004-09-17 16:35:15.000000', NULL, 1),
(914700, 104689, 24642, '<td valign="top">A good shot with a good title.</td>', 'A good shot with a good title.', '2004-09-17 16:36:20.000000', NULL, 1),
(914702, 105035, 24642, '<td valign="top">Right on man,  exciting shot.</td>', 'Right on man,  exciting shot.', '2004-09-17 16:37:00.000000', NULL, 1),
(914704, 105476, 21183, '<td valign="top">I''m so very sorry, I would really like to score this much higher, but the photo seems quite overexposed in areas and it seems sad that the player''s head has been cut off. Having said that, I do like the colour contrasts of the blue clothing and the orange frisbee beside the browns and orange of the rocks in the background and the bricks that the frisbee player is sitting on.</td>', 'I''m so very sorry, I would really like to score this much higher, but the photo seems quite overexposed in areas and it seems sad that the player''s head has been cut off. Having said that, I do like the colour contrasts of the blue clothing and the orange frisbee beside the browns and orange of the rocks in the background and the bricks that the frisbee player is sitting on.', '2004-09-17 16:40:31.000000', NULL, 1),
(914707, 104680, 24642, '<td valign="top">Very good composition and viewpoint.</td>', 'Very good composition and viewpoint.', '2004-09-17 16:43:55.000000', NULL, 1),
(914709, 105401, 21183, '<td valign="top">Umph!  Great action! - wonder if the man with the ball got pushed down?  Lovely colour in the photo, which appears to be repeated in the background. I like the focussing of this photograph (DOF).  Just wondering if that''s a little bit of dust on the lens creating that grey spot/mark to the left?  Still giving this an 8 ...and might bump higher after scoring on the rest.</td>', 'Umph!  Great action! - wonder if the man with the ball got pushed down?  Lovely colour in the photo, which appears to be repeated in the background. I like the focussing of this photograph (DOF).  Just wondering if that''s a little bit of dust on the lens creating that grey spot/mark to the left?  Still giving this an 8 ...and might bump higher after scoring on the rest.', '2004-09-17 16:46:12.000000', NULL, 1),
(914713, 105162, 21183, '<td valign="top">A really fun photograph!  I hope you print and frame this one, or put in the family album - it will be super for this boy to share with his family/friends.  Certainly made me smile.</td>', 'A really fun photograph!  I hope you print and frame this one, or put in the family album - it will be super for this boy to share with his family/friends.  Certainly made me smile.', '2004-09-17 16:49:49.000000', NULL, 1),
(914717, 104023, 16230, '<td valign="top">I''m sorry, but this is just silly. If you couldn''t come up with a decent photo you should have just passed on the challenge.</td>', 'I''m sorry, but this is just silly. If you couldn''t come up with a decent photo you should have just passed on the challenge.', '2004-09-17 16:52:48.000000', NULL, 1),
(914720, 104557, 21183, '<td valign="top">It''s interesting that you''ve had to have this photo validated, but can see why.  Looking forward to reading the ''how it was done'' when voting is over. The colour contrasts are great and really enhance this photo filled with activity!</td>', 'It''s interesting that you''ve had to have this photo validated, but can see why.  Looking forward to reading the ''how it was done'' when voting is over. The colour contrasts are great and really enhance this photo filled with activity!', '2004-09-17 16:56:25.000000', NULL, 1),
(914721, 105196, 16230, '<td valign="top">.<br/><br/><i>Message edited by author 2006-05-05 14:08:50.</i></td>', '.', '2004-09-17 16:57:05.000000', '2006-05-05 15:08:50.000000', 1),
(914727, 104887, 16230, '<td valign="top">An interesting take on the challenge. On my monitor here at work (21" Viewsonic G810) it appears to be slightly under-exposed. The colors look a bit dull. Increased exposure or a levels adjustment might have helped. I''ll have another look when I get home tonight. My Nokia monitor is much better than this Viewsonic. If it looks better on that monitor, then I''ll bump the score up a bit.</td>', 'An interesting take on the challenge. On my monitor here at work (21" Viewsonic G810) it appears to be slightly under-exposed. The colors look a bit dull. Increased exposure or a levels adjustment might have helped. I''ll have another look when I get home tonight. My Nokia monitor is much better than this Viewsonic. If it looks better on that monitor, then I''ll bump the score up a bit.', '2004-09-17 17:04:11.000000', NULL, 1),
(914732, 105204, 21183, '<td valign="top">This photograph is a refreshing sight inbetween the majority of photos submitted to the challenge.  Makes for an interesting shape - contrasted/sillhouted against the cloudless blue sky - almost like an ink blot image on blue paper and very abstract.  I would have tried to have the ball with a little more light on it, I guess, so as to make the shape a little less flat looking, though this isn''t probably what you wanted to achieve yourself.  I think you spent a lot of time and thought in creating the photograph (?) and it is still very thought provoking. Well done.</td>', 'This photograph is a refreshing sight inbetween the majority of photos submitted to the challenge.  Makes for an interesting shape - contrasted/sillhouted against the cloudless blue sky - almost like an ink blot image on blue paper and very abstract.  I would have tried to have the ball with a little more light on it, I guess, so as to make the shape a little less flat looking, though this isn''t probably what you wanted to achieve yourself.  I think you spent a lot of time and thought in creating the photograph (?) and it is still very thought provoking. Well done.', '2004-09-17 17:09:25.000000', NULL, 1),
(914737, 104858, 23478, '<td valign="top">Nice photo:)</td>', 'Nice photo:)', '2004-09-17 17:12:35.000000', NULL, 1),
(914738, 104937, 23338, '<td valign="top">Oh, gimmie a break.  TEAM SPORTS.  They have scores, umpires or refs, goals, etc.  They''re not animals out for a cruise in the sky.  Geez ...  Nice image otherwise.</td>', 'Oh, gimmie a break.  TEAM SPORTS.  They have scores, umpires or refs, goals, etc.  They''re not animals out for a cruise in the sky.  Geez ...  Nice image otherwise.', '2004-09-17 17:14:38.000000', NULL, 1),
(914740, 104630, 23338, '<td valign="top">Very nicely composed, great detail and focus, nice colors (exept the ball doesn''t fit in as well), and you really stopped them in place.  Like the way the guy in red just hangs there, off balance, with the wind blowing his shirt and even the muscles in his hand tensed to the max.   Good luck with the challenge.</td>', 'Very nicely composed, great detail and focus, nice colors (exept the ball doesn''t fit in as well), and you really stopped them in place.  Like the way the guy in red just hangs there, off balance, with the wind blowing his shirt and even the muscles in his hand tensed to the max.   Good luck with the challenge.', '2004-09-17 17:19:13.000000', NULL, 1),
(914742, 104777, 21183, '<td valign="top">What a super super photograph!  If you have the ability to do any advance editing (which I don''t myself) I''d suggest trying to edit it somehow, so as to apply the green of the playing field to the whole background (fence and trees) after voting has finished. Anyway, that said, this photo works really well for the challenge and is a good capture, showing interesting action with the players in sharp focus. Well done.</td>', 'What a super super photograph!  If you have the ability to do any advance editing (which I don''t myself) I''d suggest trying to edit it somehow, so as to apply the green of the playing field to the whole background (fence and trees) after voting has finished. Anyway, that said, this photo works really well for the challenge and is a good capture, showing interesting action with the players in sharp focus. Well done.', '2004-09-17 17:19:41.000000', NULL, 1),
(914744, 105196, 23338, '<td valign="top">You know, this image could be really improved just by cropping out the head in the lower left and down on the top until the two markers at uppper left disappear.  I know you''ll lose the player falling on his face trying to make the tackle, but you''ll emphasize the ball carrier attempting to evade and the potential tackler zeroing in.  Anyway, that would be my suggestion.   Nice image otherwise.  Good luck with the challenge.</td>', 'You know, this image could be really improved just by cropping out the head in the lower left and down on the top until the two markers at uppper left disappear.  I know you''ll lose the player falling on his face trying to make the tackle, but you''ll emphasize the ball carrier attempting to evade and the potential tackler zeroing in.  Anyway, that would be my suggestion.   Nice image otherwise.  Good luck with the challenge.', '2004-09-17 17:23:11.000000', NULL, 1),
(914748, 104072, 21183, '<td valign="top">This appears to have been a difficult photograph to capture - but you''ve achieved a good shot of the action and everything seems to be in good focus.  The legs and feet of the person standing in the background detract slightly from the rest of the image and wonder if they could have been avoided if photo had been taken from another angle.  No detriment to the photo meeting the challenge though.</td>', 'This appears to have been a difficult photograph to capture - but you''ve achieved a good shot of the action and everything seems to be in good focus.  The legs and feet of the person standing in the background detract slightly from the rest of the image and wonder if they could have been avoided if photo had been taken from another angle.  No detriment to the photo meeting the challenge though.', '2004-09-17 17:26:43.000000', NULL, 1),
(914749, 104829, 26526, '<td valign="top">Interesting concept. I just didn''t like that dof, too much blurr in the photo.</td>', 'Interesting concept. I just didn''t like that dof, too much blurr in the photo.', '2004-09-17 17:27:15.000000', NULL, 1),
(914750, 105296, 23338, '<td valign="top">Neat action.  I really wish there was a little more shown on the left, a little more on the top, a bunch more on the right, and the bottom of the image was cropped off almost half way up the grass.  Then you could see the whole of the slider, all of the edge of the dust spray, and possibly some of the second player whose feet show.   That might tell you more about what was happening or had just happened - or not.  Anyway, that''s my thoughts.  Good luck in the challenge.</td>', 'Neat action.  I really wish there was a little more shown on the left, a little more on the top, a bunch more on the right, and the bottom of the image was cropped off almost half way up the grass.  Then you could see the whole of the slider, all of the edge of the dust spray, and possibly some of the second player whose feet show.   That might tell you more about what was happening or had just happened - or not.  Anyway, that''s my thoughts.  Good luck in the challenge.', '2004-09-17 17:27:17.000000', NULL, 1),
(914752, 104076, 23338, '<td valign="top">Really clear image, both visually and metaphorically.</td>', 'Really clear image, both visually and metaphorically.', '2004-09-17 17:28:17.000000', NULL, 1),
(914755, 104495, 26526, '<td valign="top">A really good photograph. I would like to see it straightened.  Tilted photos are real diffilcult to view.</td>', 'A really good photograph. I would like to see it straightened.  Tilted photos are real diffilcult to view.', '2004-09-17 17:31:25.000000', NULL, 1),
(914756, 105485, 21183, '<td valign="top">My guess is that this is a photograph of a players shirt against an action photograph of a game of baseball?  If so, that''s a creative and novel idea for the challenge.  Title fits the photo well - it being the subject that it is - and in B&amp;W. Nicely thought out, well done.</td>', 'My guess is that this is a photograph of a players shirt against an action photograph of a game of baseball?  If so, that''s a creative and novel idea for the challenge.  Title fits the photo well - it being the subject that it is - and in B&W. Nicely thought out, well done.', '2004-09-17 17:32:37.000000', NULL, 1),
(914758, 105415, 23338, '<td valign="top">Great DOF, color, lighting and contrast.  Wish it didn''t have the distracting fence posts, etc., in the background.  Another image in there is if you cropped right to the right hand side of number 11''s right shoe, down almost to the top of her head, and right down the back of number 6, elmininating the blue and white number two.  What you would then have is an image concentrating on the two players facing off over the ball - with the ball more centered.  It would concentrate the emphasis and remove all distractions.  Just a thought.  Good luck with the challenge.</td>', 'Great DOF, color, lighting and contrast.  Wish it didn''t have the distracting fence posts, etc., in the background.  Another image in there is if you cropped right to the right hand side of number 11''s right shoe, down almost to the top of her head, and right down the back of number 6, elmininating the blue and white number two.  What you would then have is an image concentrating on the two players facing off over the ball - with the ball more centered.  It would concentrate the emphasis and remove all distractions.  Just a thought.  Good luck with the challenge.', '2004-09-17 17:34:16.000000', NULL, 1),
(914760, 104689, 26526, '<td valign="top">Therrific photo.  B&amp;W (sepia?) enhances the feeling of aged. (Not old.) One of my favorites in this contest.</td>', 'Therrific photo.  B&W (sepia?) enhances the feeling of aged. (Not old.) One of my favorites in this contest.', '2004-09-17 17:35:00.000000', NULL, 1),
(914761, 105485, 23338, '<td valign="top">You''ve obviously taken a photo of some other images which were merged together somehow.  Nice composition.  Good luck in the challenge.</td>', 'You''ve obviously taken a photo of some other images which were merged together somehow.  Nice composition.  Good luck in the challenge.', '2004-09-17 17:37:02.000000', NULL, 1),
(914767, 105255, 21183, '<td valign="top">This must have taken ages to set up?  I''m fascinated and hopefully you''ll write a bit about how this was done. It looks like you''ve had to have the photo validated, though I would never have thought it was created outside of the rules, so someone with greater knowledge of photography than myself must have requested it?  The image fits the challenge and is very humorous.  Well done.</td>', 'This must have taken ages to set up?  I''m fascinated and hopefully you''ll write a bit about how this was done. It looks like you''ve had to have the photo validated, though I would never have thought it was created outside of the rules, so someone with greater knowledge of photography than myself must have requested it?  The image fits the challenge and is very humorous.  Well done.', '2004-09-17 17:38:18.000000', NULL, 1),
(914768, 105256, 26526, '<td valign="top">Fantastic capture of the moment, the gentleman giving his all for the game. I like it in b&amp;w.  (Sepia? My moniter calibration?) One of my favorite photos in this contest.</td>', 'Fantastic capture of the moment, the gentleman giving his all for the game. I like it in b&w.  (Sepia? My moniter calibration?) One of my favorite photos in this contest.', '2004-09-17 17:38:54.000000', NULL, 1),
(914770, 104802, 23338, '<td valign="top">Nice stop of the action and timing.  Great focusing for your subject matter.  Would have rated it higher but for the distracting feet and legs elsewhere in the image.  Good luck in the challenge.</td>', 'Nice stop of the action and timing.  Great focusing for your subject matter.  Would have rated it higher but for the distracting feet and legs elsewhere in the image.  Good luck in the challenge.', '2004-09-17 17:40:03.000000', NULL, 1),
(914771, 105485, 26526, '<td valign="top">Well done.  Terrific photo rendered in sepia.</td>', 'Well done.  Terrific photo rendered in sepia.', '2004-09-17 17:41:15.000000', NULL, 1),
(914772, 105361, 24642, '<td valign="top">Good compostion and colors.</td>', 'Good compostion and colors.', '2004-09-17 17:41:32.000000', NULL, 1),
(914773, 105267, 23338, '<td valign="top">Very nice black and white composition.  One of the things I love about these kind of shots is that you can spend tons of times looking through the image for interesting side bars - such as the trio holding a conversation in the lower left, the older gentlemen hanging over the fence on the far right and the group of friends sitting on the bar behind the players.   How about the little girl with her parents right on the side lines?  Great detail and focus throughout.  Really nice tones and contrasts.  Wonderful  image.  And a different sport for this challenge.  Curious if anyone else thinks it stands out as much as I do (I do lots of LF B&amp;W).  Hope you ribbon.</td>', 'Very nice black and white composition.  One of the things I love about these kind of shots is that you can spend tons of times looking through the image for interesting side bars - such as the trio holding a conversation in the lower left, the older gentlemen hanging over the fence on the far right and the group of friends sitting on the bar behind the players.   How about the little girl with her parents right on the side lines?  Great detail and focus throughout.  Really nice tones and contrasts.  Wonderful  image.  And a different sport for this challenge.  Curious if anyone else thinks it stands out as much as I do (I do lots of LF B&W).  Hope you ribbon.', '2004-09-17 17:42:01.000000', NULL, 1),
(914774, 105446, 26526, '<td valign="top">Very good photo for this challenge. I like the composition of it.</td>', 'Very good photo for this challenge. I like the composition of it.', '2004-09-17 17:42:45.000000', NULL, 1),
(914776, 105407, 23338, '<td valign="top">Aliens vs. Predators?  :-)  Nicely balance image.  Good luck in the challenge.</td>', 'Aliens vs. Predators?  :-)  Nicely balance image.  Good luck in the challenge.', '2004-09-17 17:43:45.000000', NULL, 1),
(914778, 104937, 24642, '<td valign="top">Different.</td>', 'Different.', '2004-09-17 17:43:55.000000', NULL, 1),
(914782, 105480, 26526, '<td valign="top">Very well done! I like the lines in this photo.</td>', 'Very well done! I like the lines in this photo.', '2004-09-17 17:46:41.000000', NULL, 1),
(914787, 105400, 19912, '<td valign="top">:-)</td>', ':-)', '2004-09-17 17:48:49.000000', NULL, 1),
(914791, 105447, 26526, '<td valign="top">Great photo! Whatever it takes to protect the quarterback.</td>', 'Great photo! Whatever it takes to protect the quarterback.', '2004-09-17 17:50:46.000000', NULL, 1),
(914806, 104023, 21183, '<td valign="top">I read (above) that this has been validated, not missing and not an error, in which case I''m totally bemused - and amused!  You''ve entitled the photo as ''competition''..hmmm.. even more thought provoking! Which some pieces of ''art'' deliberately attempt to be - you''ve achieved that, certainly. According to the site rules though, I''m supposed to give consideration to the picture meeting the challenge - as there doesn''t seem to be a specific image to vote on I decided against scoring a vote.  Really looking forward to reading any reason/explanation on this one!  lol</td>', 'I read (above) that this has been validated, not missing and not an error, in which case I''m totally bemused - and amused!  You''ve entitled the photo as ''competition''..hmmm.. even more thought provoking! Which some pieces of ''art'' deliberately attempt to be - you''ve achieved that, certainly. According to the site rules though, I''m supposed to give consideration to the picture meeting the challenge - as there doesn''t seem to be a specific image to vote on I decided against scoring a vote.  Really looking forward to reading any reason/explanation on this one!  lol', '2004-09-17 18:02:20.000000', NULL, 1),
