(914831, 105445, 15002, '<td valign="top">Good action. Would like to see the expression on their faces.</td>', 'Good action. Would like to see the expression on their faces.', '2004-09-17 18:14:30.000000', NULL, 1),
(914832, 104209, 21183, '<td valign="top">This is a lovely image. Seems to portray grace, balance, concentration and focus. Gave an 8...might bump higher after finishing voting the rest.</td>', 'This is a lovely image. Seems to portray grace, balance, concentration and focus. Gave an 8...might bump higher after finishing voting the rest.', '2004-09-17 18:14:31.000000', NULL, 1),
(914852, 105198, 21183, '<td valign="top">Meets the challenge.  There''s lots of action and activity and you''ve managed to keep quite a good focus, considering everyone''s moving, I think.  The top half of the photo looks a little more cropped than you might have needed to - though I''m not sure.</td>', 'Meets the challenge.  There''s lots of action and activity and you''ve managed to keep quite a good focus, considering everyone''s moving, I think.  The top half of the photo looks a little more cropped than you might have needed to - though I''m not sure.', '2004-09-17 18:24:45.000000', NULL, 1),
(914858, 104741, 13365, '<td valign="top">You have captured the essence of team sports in this photo. The quiet reflectivity that the players must endure before and after the game is well represented.  Simply brilliant!!!</td>', 'You have captured the essence of team sports in this photo. The quiet reflectivity that the players must endure before and after the game is well represented.  Simply brilliant!!!', '2004-09-17 18:28:26.000000', NULL, 1),
