(920227, 104379, 15242, '<td valign="top">Sure it meets the challenge, but is it a good photo?</td>', 'Sure it meets the challenge, but is it a good photo?', '2004-09-21 23:26:20.000000', NULL, 1),
(920230, 104937, 15242, '<td valign="top">A "team sport" is a contest between a group of players on one team simultaneously competing with a group of players on the other team. Your challenge: capture the action of a team sport! (For clarity, your photo does not need to contain the entire team or even multiple people, the sport you are photographing just needs to be a team sport!)<br/></td>', 'A "team sport" is a contest between a group of players on one team simultaneously competing with a group of players on the other team. Your challenge: capture the action of a team sport! (For clarity, your photo does not need to contain the entire team or even multiple people, the sport you are photographing just needs to be a team sport!)', '2004-09-21 23:27:38.000000', NULL, 1),
(920234, 104388, 15242, '<td valign="top">Not only is it fuzzy/blurry, but there is nothing going on here.  You can''t take a good shot in this situation unless you have a really good camera and a lot of zoom.</td>', 'Not only is it fuzzy/blurry, but there is nothing going on here.  You can''t take a good shot in this situation unless you have a really good camera and a lot of zoom.', '2004-09-21 23:30:48.000000', NULL, 1),
(920237, 105473, 15242, '<td valign="top">Not a fan of the motion blur here.</td>', 'Not a fan of the motion blur here.', '2004-09-21 23:31:17.000000', NULL, 1),
(920244, 104495, 27105, '<td valign="top">This is a really nice photo. Friday night football sucks to shoot and this is lit very well, especially the darker skin. Looks like the stadium has nice lights!</td>', 'This is a really nice photo. Friday night football sucks to shoot and this is lit very well, especially the darker skin. Looks like the stadium has nice lights!', '2004-09-21 23:32:35.000000', NULL, 1),
