(920398, 105257, 22734, '<td valign="top">Congratulations on your yellow. Cool and the stop action is on the money with clarity to spare.</td>', 'Congratulations on your yellow. Cool and the stop action is on the money with clarity to spare.', '2004-09-22 01:05:28.000000', NULL, 0),
(920401, 104495, 8125, '<td valign="top">So Close!  Congrats on your 4th place... it''s a terrific image  :-)</td>', 'So Close!  Congrats on your 4th place... it''s a terrific image  :-)', '2004-09-22 01:06:47.000000', NULL, 0),
(920403, 104495, 22734, '<td valign="top">Hey John; A very striking entry. I did miss it. Congratulations on your 4th placing. Hey, just a breath away. It is great.</td>', 'Hey John; A very striking entry. I did miss it. Congratulations on your 4th placing. Hey, just a breath away. It is great.', '2004-09-22 01:07:20.000000', NULL, 0),
(920405, 104935, 8125, '<td valign="top">I knew this was you!!  I never made it back for commenting - but this was one of my 10''s.  Congrats Arnit on the ribbon, an awesome image  :-)</td>', 'I knew this was you!!  I never made it back for commenting - but this was one of my 10''s.  Congrats Arnit on the ribbon, an awesome image  :-)', '2004-09-22 01:08:13.000000', NULL, 0),
