(920421, 104887, 22734, '<td valign="top">Congratulations on your 7th placing. Great composition filling the frame with blue like this.</td>', 'Congratulations on your 7th placing. Great composition filling the frame with blue like this.', '2004-09-22 01:11:06.000000', NULL, 0),
(920424, 105400, 22734, '<td valign="top">Congratulations on your 8th placing. Eddie G you are an amazing photographer. Great shot.</td>', 'Congratulations on your 8th placing. Eddie G you are an amazing photographer. Great shot.', '2004-09-22 01:12:14.000000', NULL, 0),
(920426, 104730, 19982, '<td valign="top">Okay... I have 2 daughters and one son on the swim team.  You would be hard pressed to convince them that swimming is not a "team sport" (races are performed as a team, scoring is based on team results and some races, such as relays, actually require multiple participants in a single lane to obtain a score).<br/> <br/>Still...  I get what everyone is saying.  Those that couldn''t think of swimming as a "team sport" were looking more for physical contact or interaction between team members rather than just team participation.  I understand.  The challenge, of course, did not say any such interaction was necessary.  But I do appreciate the feedback.<br/> <br/>I also appreciate the votes that were given!  Thanks!</td>', 'Okay... I have 2 daughters and one son on the swim team.  You would be hard pressed to convince them that swimming is not a "team sport" (races are performed as a team, scoring is based on team results and some races, such as relays, actually require multiple participants in a single lane to obtain a score). Still...  I get what everyone is saying.  Those that couldn''t think of swimming as a "team sport" were looking more for physical contact or interaction between team members rather than just team participation.  I understand.  The challenge, of course, did not say any such interaction was necessary.  But I do appreciate the feedback. I also appreciate the votes that were given!  Thanks!', '2004-09-22 01:13:24.000000', NULL, 0),
(920428, 104630, 22734, '<td valign="top">Congratulations on your 9th placing. Fantastic view. the agility and the chase very well presented.</td>', 'Congratulations on your 9th placing. Fantastic view. the agility and the chase very well presented.', '2004-09-22 01:13:50.000000', NULL, 0),
(920432, 104802, 22734, '<td valign="top">Congratulations on your 10th placing with this super exciting image.</td>', 'Congratulations on your 10th placing with this super exciting image.', '2004-09-22 01:14:43.000000', NULL, 0),
