(920436, 105235, 22734, '<td valign="top">Congratulations on your 12th placing. This was one of my favs. very well done and top 20 is cool.</td>', 'Congratulations on your 12th placing. This was one of my favs. very well done and top 20 is cool.', '2004-09-22 01:16:17.000000', NULL, 0),
