(920446, 105446, 22734, '<td valign="top">Congratulations on your 14th placing. Lovely colors, strength and action.</td>', 'Congratulations on your 14th placing. Lovely colors, strength and action.', '2004-09-22 01:18:40.000000', NULL, 0),
