(920455, 104023, 25483, '<td valign="top">seven 10''s, 65 comments, 1 favorites <br/> <br/>As smokeditor put it: Pure Genius :)<br/><br/><i>Message edited by author 2004-09-22 00:21:28.</i></td>', 'seven 10''s, 65 comments, 1 favorites  As smokeditor put it: Pure Genius :)', '2004-09-22 01:20:22.000000', '2004-09-22 01:21:28.000000', 0),
(920458, 105447, 22734, '<td valign="top">Congratulations on your 16th placing. Great capture. Very professional.</td>', 'Congratulations on your 16th placing. Great capture. Very professional.', '2004-09-22 01:21:06.000000', NULL, 0),
(920459, 104741, 3306, '<td valign="top">Boy, What a mistake. I was considering using this picture in the Master''s Challenge and had uploaded 2 versions of the picture. One version I put in the Master''s Challenge and the other one in the Action Sports Challenge so that I could see how each looked online. I forgot to unsubmit this version! Now, I not only got killed in this challenge but I can''t use the picture for the Master''s Challenge either. To make matters worse my camera is at the shop for repairs and may not be back in time for me to take a picture for the Master''s Challenge :(. The only consolation is getting to read all the comments people made on this picture. It apparently received quite a bit of attention. Thanks to all for your comments.</td>', 'Boy, What a mistake. I was considering using this picture in the Master''s Challenge and had uploaded 2 versions of the picture. One version I put in the Master''s Challenge and the other one in the Action Sports Challenge so that I could see how each looked online. I forgot to unsubmit this version! Now, I not only got killed in this challenge but I can''t use the picture for the Master''s Challenge either. To make matters worse my camera is at the shop for repairs and may not be back in time for me to take a picture for the Master''s Challenge :(. The only consolation is getting to read all the comments people made on this picture. It apparently received quite a bit of attention. Thanks to all for your comments.', '2004-09-22 01:21:12.000000', NULL, 0),
(920472, 104730, 22734, '<td valign="top">hey David; this is a top notch shot.  Congratulations on your 17th placing. Very good work.</td>', 'hey David; this is a top notch shot.  Congratulations on your 17th placing. Very good work.', '2004-09-22 01:23:29.000000', NULL, 0),
